for (let i = 1; i < 51; ++i) {
	if (i % 3 == 0 && i % 5 == 0) {
		printToScreen("FizzBuzz");
	} else if (i % 3 == 0) {
		printToScreen("Fizz");
	} else if (i % 5 == 0) {
		printToScreen("Buzz");
	} else {
		printToScreen(i);
	}
}

