// Ask the user for two numbers. Find the greatest common factor (also called the greatest common divisor or GCD) between the two numbers, and print it out using printToScreen(). The GCF is the largest number which can divide 2 other numbers with no remainder. For example, the GCF of the numbers 36 and 24 is 12.

// Solution

let numOne = +prompt("Enter a number: ");
let numTwo = +prompt("Enter another number: ");

let larger = numOne;
if (numOne < numTwo) {
	larger = numTwo;
}

let gCD = 1;

for (let i = 0; i <= larger; i++) {
	if (numOne % i === 0 && numTwo % i === 0) {
		gCD = i;
	}
}

printToScreen(gCD);

